def frames(g):
    from collections import defaultdict
    boxes=defaultdict(list)
    seen=set()
    H,W=len(g),len(g[0])
    for i in range(H):
        for j in range(W):
            c=g[i][j]
            if c and c not in seen and (i==0 or g[i-1][j]!=c or j==0 or g[i][j-1]!=c):
                # find bbox of this color's frame (assume one frame per color)
                cells=[(a,b) for a in range(H) for b in range(W) if g[a][b]==c]
                rs=[a for a,b in cells]; cs=[b for a,b in cells]
                boxes[c]=(min(rs),min(cs),max(rs),max(cs))
                seen.add(c)
    return boxes
