def transform(g):
    H,W=len(g),len(g[0])
    fs=[]
    for c in sorted({v for row in g for v in row if v}):
        cells=[(a,b) for a in range(H) for b in range(W) if g[a][b]==c]
        r0=min(a for a,b in cells);c0=min(b for a,b in cells);r1=max(a for a,b in cells);c1=max(b for a,b in cells)
        pat=[row[c0+1:c1] for row in g[r0+1:r1]]
        fs.append((c,(r0,c0,r1,c1),pat,any(any(r) for r in pat)))
    out=[row[:] for row in g]
    src=[(c,pat) for c,b,pat,f in fs if f and pat]
    for c,b,pat,f in fs:
        if f: continue
        r0,c0,r1,c1=b
        h=len(pat);w=len(pat[0]) if pat else 0
        m=[(sc,sp) for sc,sp in src if len(sp)==h and len(sp[0])==w]
        if len(m)==1:
            sc,sp=m[0]
            for a in range(r0+1,r1):
                for j in range(c0+1,c1):
                    if sp[a-r0-1][j-c0-1]: out[a][j]=c
        else:
            for a in range(r0,r1+1):
                for j in range(c0,c1+1):
                    if out[a][j]==c: out[a][j]=0
    return out
